function parseCli(argv: readonly string[]): CliParseResult {
  const [first] = argv;
  const help = parseCliHelp(argv);
  if (help !== null) return help;
  const commandToken =
    first === undefined || first.startsWith("-") ? "check" : first;
  if (!isCommand(commandToken)) {
    return { error: `unknown command: ${commandToken}`, status: "invalid" };
  }
  const tokens = first === commandToken ? argv.slice(1) : argv;
  return parseCommandTokens(commandToken, tokens);
}

function parseCliHelp(argv: readonly string[]): CliParseResult | null {
  const [first] = argv;
  if (first === "-h" || first === "--help") return { status: "help" };
  if (first !== "help") return null;
  const requested = argv[1];
  if (requested === undefined) return { status: "help" };
  if (!isCommand(requested) || argv.length !== 2) {
    return {
      error: `unknown command: ${requested ?? ""}`,
      status: "invalid"
    };
  }
  return { command: requested, status: "help" };
}

function parseCommandTokens(
  command: InvestigationCommand,
  tokens: readonly string[]
): CliParseResult {
  const context: CliTokenContext = { positionals: [], values: new Map() };
  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index]!;
    const parsed = parseCommandToken(token, tokens[index + 1], context);
    if (parsed.error !== null) {
      return { error: parsed.error, status: "invalid" };
    }
    if (parsed.consumedNext) index += 1;
  }
  if (context.values.has("help")) {
    return { command, status: "help" };
  }
  normalizeIdentitySelectorsAtCliBoundary(command, context);
  return {
    status: "command",
    value: { command, ...context }
  };
}

function normalizeIdentitySelectorsAtCliBoundary(
  command: InvestigationCommand,
  context: CliTokenContext
): void {
  if (
    [
      "new",
      "discard",
      "discard-candidate",
      "show",
      "show-candidate",
      "publish",
      "rename",
      "stage-index",
      "trace"
    ].includes(command)
  ) {
    context.positionals.splice(
      0,
      context.positionals.length,
      ...context.positionals.map(normalizeCompatibleInvestigationId)
    );
  }
  for (const option of ["id", "source"] as const) {
    const values = context.values.get(option);
    if (values !== undefined) {
      context.values.set(
        option,
        values.map(normalizeCompatibleInvestigationId)
      );
    }
  }
  const relations = context.values.get("relation");
  if (relations !== undefined) {
    context.values.set(
      "relation",
      relations.map(normalizeCompatibleRelationTarget)
    );
  }
  const relationSummaries = context.values.get("relation-summary");
  if (relationSummaries !== undefined) {
    context.values.set(
      "relation-summary",
      relationSummaries.map(normalizeCompatibleRelationSummaryTarget)
    );
  }
}

function normalizeCompatibleInvestigationId(value: string): string {
  return normalizeInvestigationIdInput(value) ?? value;
}

function normalizeCompatibleRelationTarget(value: string): string {
  const separator = value.indexOf("=");
  if (separator < 0) return value;
  const target = normalizeInvestigationIdInput(value.slice(separator + 1));
  return target === null ? value : value.slice(0, separator + 1) + target;
}

function normalizeCompatibleRelationSummaryTarget(value: string): string {
  const separator = value.indexOf("=");
  if (separator < 0) return value;
  const target = normalizeInvestigationIdInput(value.slice(0, separator));
  return target === null ? value : target + value.slice(separator);
}

function parseCommandToken(
  token: string,
  nextToken: string | undefined,
  context: CliTokenContext
): { consumedNext: boolean; error: string | null } {
  if (token === "-h" || token === "--help") {
    context.values.set("help", ["true"]);
    return { consumedNext: false, error: null };
  }
  if (!token.startsWith("--")) {
    context.positionals.push(token);
    return { consumedNext: false, error: null };
  }
  const option = token.slice(2);
  const separator = option.indexOf("=");
  const rawName = separator < 0 ? option : option.slice(0, separator);
  const inlineValue = separator < 0 ? undefined : option.slice(separator + 1);
  if (!valueOptions.has(rawName) && !booleanOptions.has(rawName)) {
    return { consumedNext: false, error: `unknown option: ${token}` };
  }
  if (booleanOptions.has(rawName)) {
    return parseBooleanCommandOption(token, rawName, inlineValue, context);
  }
  return parseValueCommandOption(
    token,
    rawName,
    inlineValue,
    nextToken,
    context
  );
}

function parseBooleanCommandOption(
  token: string,
  name: string,
  inlineValue: string | undefined,
  context: CliTokenContext
): { consumedNext: false; error: string | null } {
  if (inlineValue !== undefined) {
    return { consumedNext: false, error: `${token} does not accept a value` };
  }
  context.values.set(name, [...(context.values.get(name) ?? []), "true"]);
  return { consumedNext: false, error: null };
}

function parseValueCommandOption(
  token: string,
  name: string,
  inlineValue: string | undefined,
  nextToken: string | undefined,
  context: CliTokenContext
): { consumedNext: boolean; error: string | null } {
  const value = inlineValue ?? nextToken;
  if (value === undefined || value.startsWith("--")) {
    return { consumedNext: false, error: `${token} requires a value` };
  }
  context.values.set(name, [...(context.values.get(name) ?? []), value]);
  return { consumedNext: inlineValue === undefined, error: null };
}

function isCommand(value: string): value is InvestigationCommand {
  return [
    "new",
    "candidates",
    "check",
    "discard",
    "discard-candidate",
    "sync-index",
    "list",
    "search",
    "show",
    "show-candidate",
    "publish",
    "rename",
    "trace",
    "stage-index",
    "set-relations"
  ].includes(value);
}

function valueOf(
  values: ReadonlyMap<string, string[]>,
  key: string
): string | undefined {
  const valuesForKey = values.get(key);
  return valuesForKey?.length === 1 ? valuesForKey[0] : undefined;
}
function valuesOf(
  values: ReadonlyMap<string, string[]>,
  key: string
): string[] | undefined {
  const valuesForKey = values.get(key);
  return valuesForKey === undefined ? undefined : [...valuesForKey];
}
function has(values: ReadonlyMap<string, string[]>, key: string): boolean {
  return values.has(key);
}
function location(values: ReadonlyMap<string, string[]>): {
  investigationsDir?: string;
  workspaceRoot: string;
} {
  const investigationsDir = valueOf(values, "investigations-dir");
  const workspaceRoot = valueOf(values, "root") ?? ".";
  return investigationsDir === undefined
    ? { workspaceRoot }
    : { investigationsDir, workspaceRoot };
}
function numberValue(
  values: ReadonlyMap<string, string[]>,
  key: string
): number | undefined {
  const value = valueOf(values, key);
  return value === undefined ? undefined : Number(value);
}
function commonInvestigationQueryOptions(
  input: ParsedCli
): CommonInvestigationQueryOptions {
  const { values } = input;
  const tags = valuesOf(values, "tag");
  const formedAtFrom = valueOf(values, "formed-from");
  const formedAtTo = valueOf(values, "formed-to");
  const relatedTo = valueOf(values, "related-to");
  const direction = valueOf(values, "direction");
  const relationType = valueOf(values, "relation-type");
  const limit = numberValue(values, "limit");
  return {
    ...location(values),
    ...(tags === undefined ? {} : { tags }),
    ...(formedAtFrom === undefined ? {} : { formedAtFrom }),
    ...(formedAtTo === undefined ? {} : { formedAtTo }),
    ...(relatedTo === undefined ? {} : { relatedTo }),
    ...(direction === undefined ? {} : { direction }),
    ...(relationType === undefined ? {} : { relationType }),
    ...(limit === undefined ? {} : { limit })
  };
}
function assertNoPositionals(input: ParsedCli): string | null {
  return input.positionals.length === 0
    ? null
    : `${input.command} does not accept positional arguments`;
}
function assertAllowedOptions(
  input: ParsedCli,
  allowed: readonly string[]
): string | null {
  const invalid = [...input.values.keys()].find(
    (key) => !key.startsWith("__") && !allowed.includes(key)
  );
  return invalid === undefined
    ? null
    : `${input.command} does not accept --${invalid}`;
}
function assertSingleOptions(
  input: ParsedCli,
  options: readonly string[]
): string | null {
  const repeated = options.find(
    (option) => (input.values.get(option)?.length ?? 0) > 1
  );
  return repeated === undefined
    ? null
    : `${input.command} accepts --${repeated} only once`;
}

async function runNew(
  input: ParsedCli,
  io: InvestigationReportCliIo
): Promise<number> {
  const prepared = prepareNewCandidateInput(input);
  if ("error" in prepared) return cliInvalid(prepared.error, io);
  const result = await createInvestigationCandidateFromCli(
    prepared.value.input,
    prepared.value.relationSummaries
  );
  if (result.status !== "ok") {
    return printResultErrors(
      result.status === "invalid-options"
        ? "Invalid investigation candidate options:"
        : "Investigation candidate creation failed:",
      result.errors,
      result.status === "invalid-options" ? 2 : 1,
      result.warnings,
      io,
      result.diagnostics
    );
  }
  writeLine(
    io.stdout,
    `Investigation candidate created: ${result.candidate.path}`
  );
  printWarnings(result.warnings, io);
  printCandidateReadiness(result.candidate, io);
  await printNewCandidatePublishPreflight(
    prepared.value.id,
    location(input.values),
    io
  );
  return 0;
}

function prepareNewCandidateInput(input: ParsedCli):
  | { error: string }
  | {
      value: {
        id: string;
        input: unknown;
        relationSummaries: InvestigationRelationSummaryInput[];
      };
    } {
  const problem =
    assertAllowedOptions(input, [
      "root",
      "investigations-dir",
      "title",
      "formed-at",
      "question",
      "tag",
      "relation",
      "relation-summary"
    ]) ??
    (input.positionals.length === 1
      ? null
      : "new requires exactly one Investigation ID");
  if (problem !== null) return { error: problem };
  const [id] = input.positionals;
  const title = valueOf(input.values, "title");
  const formedAt = valueOf(input.values, "formed-at");
  const question = valueOf(input.values, "question");
  const tags = valuesOf(input.values, "tag");
  if (
    id === undefined ||
    title === undefined ||
    formedAt === undefined ||
    question === undefined ||
    tags === undefined
  ) {
    return {
      error:
        "new requires --title, --formed-at, --question, and at least one --tag"
    };
  }
  const relations = parseNewRelations(valuesOf(input.values, "relation") ?? []);
  if (relations.status === "error") return { error: relations.error };
  const relationSummaries = parseRelationSummaries(
    valuesOf(input.values, "relation-summary") ?? []
  );
  return relationSummaries.status === "error"
    ? { error: relationSummaries.error }
    : relationSummaries.values.length > 0 && relations.values.length === 0
      ? { error: "--relation-summary requires at least one --relation" }
      : {
          value: {
            id,
            input: {
              ...location(input.values),
              formedAt,
              id,
              question,
              relations: relations.values,
              tags,
              title
            },
            relationSummaries: relationSummaries.values
          }
        };
}

async function printNewCandidatePublishPreflight(
  id: string,
  candidateLocation: { investigationsDir?: string; workspaceRoot: string },
  io: InvestigationReportCliIo
): Promise<void> {
  const preflight = await publishInvestigationCandidates({
    ...candidateLocation,
    ids: [id],
    preflight: true
  });
  if (preflight.errors.length === 0) {
    writeLine(io.stderr, "Candidate publish preflight: ready.");
    printWarnings(preflight.warnings, io);
    return;
  }
  writeLine(io.stderr, "Candidate publish preflight: needs attention.");
  for (const error of preflight.errors) writeLine(io.stderr, `- ${error}`);
  printWarnings(preflight.warnings, io);
  writeLine(
    io.stderr,
    "  next: keep the created candidate, edit it or inspect it with show-candidate, then rerun publish --preflight; do not rerun new"
  );
}

async function runPublish(
  input: ParsedCli,
  io: InvestigationReportCliIo
): Promise<number> {
  const problem = assertAllowedOptions(input, [
    "root",
    "investigations-dir",
    "preflight"
  ]);
  if (problem !== null || input.positionals.length === 0) {
    return cliInvalid(
      problem ?? "publish requires at least one Investigation selector",
      io
    );
  }
  if (new Set(input.positionals).size !== input.positionals.length) {
    return cliInvalid("publish IDs must not repeat", io);
  }
  const published = await publishInvestigationCandidates({
    ...location(input.values),
    ids: input.positionals,
    preflight: has(input.values, "preflight")
  });
  if (published.errors.length > 0) {
    printResultErrors(
      published.preflight
        ? "Investigation publish preflight failed:"
        : "Investigation publish failed:",
      published.errors,
      1,
      published.warnings,
      io,
      published.diagnostics
    );
    return 1;
  }
  printWarnings(published.warnings, io);
  writeLine(
    io.stdout,
    published.preflight
      ? `Investigation publish preflight passed (${published.ids.join(", ")}); no candidate, formal report, resource, index, or pending state was changed.`
      : `Investigation candidates published: ${published.ids.join(", ")}.`
  );
  return 0;
}

